import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { createVendorProduct, getCategories, getVendorProducts, submitVendorProduct } from "../catalog/catalog.api";
import { getVendorWorkspace } from "./vendor.api";

export function VendorProductsScreen() {
  const user = firebaseAuth?.currentUser ?? null; const queryClient = useQueryClient();
  const products = useQuery({ queryKey: ["vendor", "products"], queryFn: () => getVendorProducts(user!), enabled: Boolean(user) });
  const categories = useQuery({ queryKey: ["catalog", "categories"], queryFn: getCategories });
  const workspace = useQuery({ queryKey: ["vendor", "workspace"], queryFn: () => getVendorWorkspace(user!), enabled: Boolean(user) });
  const [form, setForm] = useState({ name: "", sku: "", price: "", stock: "0", description: "" });
  const create = useMutation({ mutationFn: () => createVendorProduct(user!, { shopId: workspace.data!.shops[0]!.id, categoryId: categories.data![0]!.id, name: form.name, slug: form.name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""), description: form.description || null, variants: [{ sku: form.sku, title: "Default", priceMinor: String(Math.round(Number(form.price) * 100)), currency: "BDT", onHand: Number(form.stock) }] }), onSuccess: async () => { setForm({ name: "", sku: "", price: "", stock: "0", description: "" }); await queryClient.invalidateQueries({ queryKey: ["vendor", "products"] }); } });
  const submit = useMutation({ mutationFn: (id: string) => submitVendorProduct(user!, id), onSuccess: () => queryClient.invalidateQueries({ queryKey: ["vendor", "products"] }) });
  const ready = Boolean(workspace.data?.shops[0] && categories.data?.[0]);
  return <Screen eyebrow="SELLER CENTER" title="Products" description="Create listings, review moderation state, and submit drafts for approval."><ModuleCard title="Add product" meta={ready ? `Shop: ${workspace.data!.shops[0]!.name} · Category: ${categories.data![0]!.name}` : "Loading shop and category…"}><Field label="Product name" value={form.name} onChangeText={(name) => setForm({ ...form, name })} /><Field label="SKU" value={form.sku} onChangeText={(sku) => setForm({ ...form, sku })} /><View style={styles.row}><View style={styles.flex}><Field keyboardType="numeric" label="Price (BDT)" value={form.price} onChangeText={(price) => setForm({ ...form, price })} /></View><View style={styles.flex}><Field keyboardType="numeric" label="Opening stock" value={form.stock} onChangeText={(stock) => setForm({ ...form, stock })} /></View></View><Field label="Description" multiline value={form.description} onChangeText={(description) => setForm({ ...form, description })} />{create.error ? <Text style={styles.error}>{create.error.message}</Text> : null}<Pressable disabled={!ready || create.isPending || form.name.length < 3 || form.sku.length < 3 || Number(form.price) <= 0} onPress={() => create.mutate()} style={styles.primary}>{create.isPending ? <ActivityIndicator color="#fff" /> : <Text style={styles.primaryText}>Create draft</Text>}</Pressable></ModuleCard>{products.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{products.data?.map((product) => <ModuleCard key={product.id} title={product.name} meta={`${product.status} · ${product.variants.length} variant`}><Text style={styles.muted}>{product.description || "No description"}</Text><Text style={styles.price}>৳{(Number(product.minimumPrice.amountMinor) / 100).toLocaleString("en-BD")}</Text>{product.status === "DRAFT" || product.status === "REJECTED" ? <Pressable onPress={() => submit.mutate(product.id)} style={styles.secondary}><Text style={styles.secondaryText}>Submit for approval</Text></Pressable> : null}</ModuleCard>)}</Screen>;
}
function Field(props: React.ComponentProps<typeof TextInput> & { label: string }) { const { label, ...rest } = props; return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput placeholderTextColor={colors.muted} style={[styles.input, rest.multiline && styles.multiline]} {...rest} /></View>; }
const styles = StyleSheet.create({ row: { flexDirection: "row", gap: spacing.sm }, flex: { flex: 1 }, field: { gap: 5 }, label: { color: colors.text, fontSize: 12, fontWeight: "800" }, input: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 46, paddingHorizontal: 12 }, multiline: { minHeight: 90, paddingVertical: 10, textAlignVertical: "top" }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 46 }, primaryText: { color: "#fff", fontWeight: "900" }, secondary: { alignItems: "center", borderColor: colors.primary, borderRadius: radius.md, borderWidth: 1, minHeight: 42, justifyContent: "center" }, secondaryText: { color: colors.primary, fontWeight: "900" }, error: { color: colors.danger }, muted: { color: colors.muted }, price: { color: colors.text, fontSize: 18, fontWeight: "900" } });
